export default function Home() {
  const experiences = [
    {
      title: "Amazon Web Services (AWS)",
      role: "Software Development Engineer Intern",
      link: "https://aws.amazon.com/s3/glacier/",
    },
    {
      title: "Primarius Technologies",
      role: "Research Intern",
      link: "https://www.primariustech.com/",
    },
    {
      title: "RoadFlex",
      role: "Head of Credit Underwriting",
      link: "https://www.roadflex.com/",
    },
  ];

  const projects = [
    {
      title: "Zero-Shot Reference-Based Image Editing",
      description: "Developed a novel AI-based image editing technique with zero-shot adaptation.",
      link: "/project-pdf",
    },
    {
      title: "Victoris",
      description: "Founded an EdTech mentorship platform helping 1,000+ students worldwide.",
      link: "#",
    },
  ];

  const smallProjects = [
    { title: "CS180 Project 1", description: "Image processing pipeline", link: "#" },
    { title: "CS180 Project 2", description: "Neural network for object detection", link: "#" },
    { title: "Personal Website", description: "This website built with React & Tailwind", link: "#" },
  ];

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center px-6">
      {/* Hero Section */}
      <div className="max-w-3xl text-center mt-16">
        <h1 className="text-4xl font-semibold text-gray-900">Kelvin Li</h1>
        <p className="text-gray-600 mt-2">
          Software Engineer & AI Researcher | UC Berkeley  
          <br /> B.S. in EECS & Mathematics (2022–2025)
        </p>
        <div className="mt-4 flex justify-center space-x-4">
          <a href="https://linkedin.com/in/kelvinli" className="text-blue-600 hover:underline">LinkedIn</a>
          <a href="https://github.com/kelvinli" className="text-blue-600 hover:underline">GitHub</a>
          <a href="mailto:kelvin.li@email.com" className="text-blue-600 hover:underline">Email</a>
        </div>
      </div>

      {/* Experience Cards - First Row */}
      <div className="mt-12 grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl">
        {experiences.map((exp, index) => (
          <a key={index} href={exp.link} target="_blank" rel="noopener noreferrer"
            className="p-6 bg-white shadow-md rounded-lg hover:shadow-xl transition">
            <h2 className="text-lg font-semibold text-gray-900">{exp.title}</h2>
            <p className="text-gray-600 text-sm">{exp.role}</p>
            <p className="text-gray-500 text-sm mt-2">{exp.description}</p>
          </a>
        ))}
      </div>

      {/* Research & Victoris - Second Row */}
      <div className="mt-12 grid grid-cols-1 md:grid-cols-2 gap-6 max-w-5xl">
        {projects.map((project, index) => (
          <a key={index} href={project.link} target="_blank" rel="noopener noreferrer"
            className="p-6 bg-white shadow-md rounded-lg hover:shadow-xl transition">
            <h2 className="text-lg font-semibold text-gray-900">{project.title}</h2>
            <p className="text-gray-500 text-sm mt-2">{project.description}</p>
          </a>
        ))}
      </div>

      {/* Divider */}
      <div className="w-24 border-b-2 border-gray-400 my-12"></div>

      {/* Small Projects Title */}
      <h2 className="text-xl font-semibold text-gray-800">Projects</h2>

      {/* Small Projects - Grid */}
      <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl">
        {smallProjects.map((proj, index) => (
          <a key={index} href={proj.link} target="_blank" rel="noopener noreferrer"
            className="p-6 bg-white shadow-md rounded-lg hover:shadow-xl transition">
            <h2 className="text-lg font-semibold text-gray-900">{proj.title}</h2>
            <p className="text-gray-500 text-sm mt-2">{proj.description}</p>
          </a>
        ))}
      </div>
    </div>
  );
}
